// Robustly extract query from either transcription or direct text body
const transcribedText = $("Groq Whisper STT").isExecuted ? $("Groq Whisper STT").first().json.text : null;

// For text-only requests, the query may be in body.query or body fields
const webhookBody = $node["Voice Agent Webhook"]?.json?.body || {};
const bodyQuery = webhookBody.query || webhookBody.text || null;

const finalQuery = transcribedText || bodyQuery || "no query";

// Detect language: prefer explicitly sent language, fallback to 'en'
const language = webhookBody.language || 'en';

return {
  query: finalQuery,
  transcribed_text: transcribedText || bodyQuery || '',
  language
};

const response = $node["Classify Intent (Groq)"].json.choices[0].message.content || "general_question";
const intent = response.toLowerCase().trim();
const validIntents = ["research", "weather", "data_query", "general_question"];

return {
  intent: validIntents.includes(intent) ? intent : "general_question",
  query: $node["Final Query"].json.query,
  session_id: $node["Voice Agent Webhook"].json.body.session_id || "default",
  language: $node["Voice Agent Webhook"].json.body.language || "en"
};

if ($node["Search Web (Serper)"].json.error || !$node["Search Web (Serper)"].json.organic) {
  return {
    error: true,
    pipeline: "research",
    message: "I'm sorry, I couldn't retrieve that information right now."
  };
}

return {
  results: $node["Search Web (Serper)"].json.organic.slice(0, 5).map(r => ({
    title: r.title,
    snippet: r.snippet,
    url: r.link
  }))
};

if ($node["Fetch Weather"].json.error || !$node["Fetch Weather"].json.main) {
  return {
    error: true,
    pipeline: "weather",
    message: "I'm sorry, I couldn't retrieve that information right now."
  };
}

const data = $node["Fetch Weather"].json;
return {
  location: data.name,
  temperature: data.main.temp,
  condition: data.weather[0].description,
  humidity: data.main.humidity,
  wind_speed: data.wind.speed
};

const items = $input.all();
if (items.length === 0 || (items[0].json && items[0].json.error)) {
  return {
    error: true,
    pipeline: "data_query",
    message: "I'm sorry, I couldn't find any matching records in Airtable."
  };
}

return {
  records: items.map(i => i.json.fields),
  count: items.length,
  source: "airtable"
};

