const err = $input.first().json;
const errorMessage = err.error?.message || err.message || 'An unexpected error occurred';
const nodeName = err.execution?.lastNodeExecuted || 'unknown node';

console.error('[Voice Assistant Error]', nodeName, errorMessage);

return {
  response: 'I am sorry, I encountered a technical issue and could not complete your request. Please try again.',
  transcribed_text: '',
  error: true,
  error_detail: errorMessage,
  failed_node: nodeName,
  timestamp: new Date().toISOString()
};

// Installation settings. Explicitly disable here to prevent all research requests.
const enabled = true;
const provider = 'auto'; // auto, parallel, serper, or disabled
const body = $node["Voice Agent Webhook"].json.body || {};
const input = $input.first().json;
const fail = message => ({ ...input, search_provider: 'disabled', error: true, message });
if (!enabled || provider === 'disabled' || body.search_enabled === false) {
  return fail('Web research is disabled.');
}
const requested = body.search_provider ?? provider;
if (!['auto', 'parallel', 'serper', 'disabled'].includes(requested)) {
  return fail('Unknown search provider. Choose parallel or serper.');
}
if (requested === 'disabled') return fail('Web research is disabled.');
// Read the existing node settings without executing it or copying its credentials.
const settings = $node["Search Web (Serper)"].parameter;
let key;
if (settings.specifyHeaders === 'json') {
  try {
    const raw = settings.jsonHeaders;
    const headers = typeof raw === 'string' ? JSON.parse(raw) : raw;
    key = Object.entries(headers || {}).find(([name]) => name.toLowerCase() === 'x-api-key')?.[1];
  } catch {
    // An explicitly configured but invalid Serper header must not select another service.
    return { ...input, search_provider: 'serper', search_allowed: true };
  }
} else {
  key = settings.headerParameters?.parameters?.find(h => String(h.name).toLowerCase() === 'x-api-key')?.value;
}
const hasKey = typeof key === 'string' && key.trim() !== '' && key.trim() !== 'YOUR_SERPER_API_KEY';
const hasAuth = settings.authentication && settings.authentication !== 'none';
const customEndpoint = settings.url !== 'https://google.serper.dev/search';
const selected = requested === 'auto' ? (hasKey || hasAuth || customEndpoint ? 'serper' : 'parallel') : requested;
return { ...input, search_provider: selected, search_allowed: true };

function rpc(body) {
  if (typeof body !== 'string') return body;
  try { return JSON.parse(body); } catch {}
  // Streamable HTTP may return an SSE message instead of a JSON document.
  const frames = body.split(/\r?\n\r?\n/);
  for (const frame of frames) {
    const data = frame.split(/\r?\n/).filter(l => l.startsWith('data:')).map(l => l.slice(5).trimStart()).join('\n');
    if (!data) continue;
    try { const value = JSON.parse(data); if (value.id !== undefined) return value; } catch {}
  }
  throw new Error('Invalid Parallel MCP response');
}
const response = $input.first().json;
const message = rpc(response.body);
if (message?.id !== 1 || message.error || !message.result?.capabilities?.tools ||
    !['2025-03-26', '2025-06-18', '2025-11-25'].includes(message.result.protocolVersion)) {
  throw new Error('Parallel MCP initialization failed');
}
return { protocolVersion: message.result.protocolVersion, sessionId: response.headers?.['mcp-session-id'] || '' };

function rpc(body) {
  if (typeof body !== 'string') return body;
  try { return JSON.parse(body); } catch {}
  // Streamable HTTP may return an SSE message instead of a JSON document.
  const frames = body.split(/\r?\n\r?\n/);
  for (const frame of frames) {
    const data = frame.split(/\r?\n/).filter(l => l.startsWith('data:')).map(l => l.slice(5).trimStart()).join('\n');
    if (!data) continue;
    try { const value = JSON.parse(data); if (value.id !== undefined) return value; } catch {}
  }
  throw new Error('Invalid Parallel MCP response');
}
const response = $input.first().json;
const failure = { error: true, pipeline: 'research', message: "I'm sorry, I couldn't retrieve that information right now." };
try {
  if (response.error) return failure;
  const message = rpc(response.body);
  if (message?.id !== 2 || message.error || message.result?.isError) return failure;
  const result = message.result;
  let data = result?.structuredContent;
  if (!data) {
    const text = result?.content?.find(c => c.type === 'text')?.text;
    data = typeof text === 'string' ? JSON.parse(text) : text;
  }
  if (!Array.isArray(data?.results)) return failure;
  const results = data.results.filter(r => typeof r.url === 'string' && /^https?:\/\//i.test(r.url)).slice(0, 5).map(r => ({
    title: r.title || r.url,
    snippet: Array.isArray(r.excerpts) ? r.excerpts.filter(e => typeof e === 'string').join('\n') : '',
    url: r.url
  }));
  return results.length ? { results } : failure;
} catch { return failure; }

const input = $input.first().json;
if (input.search_allowed !== true) {
  return { ...input, search_provider: 'disabled', error: true, message: input.message || 'Web research is disabled.' };
}
return input;
